package au.com.roningroup.patrollink;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public final class TabletPolicyTest {
 private CheckpointGate.Candidate c(String id,float d,float r){return new CheckpointGate.Candidate(id,d,r);}
 private CheckpointGate.Entry step(CheckpointGate gate,float distance,float radius,float accuracy,long stamp){return gate.update(Arrays.asList(c("qr",distance,radius)),accuracy,0,stamp,true,1000+stamp);}
 @Test public void fiveTenFifteenMetresAreValidAndInvalidRadiiRejected(){for(float r:new float[]{1,5,10,15,20,25,50,500})assertEquals(r,TabletPolicy.radius(r),0);for(float r:new float[]{0,-1,501,Float.NaN,Float.POSITIVE_INFINITY}){try{TabletPolicy.radius(r);fail("invalid radius accepted");}catch(IllegalArgumentException expected){}}}
 @Test public void fiveMetreRadiusRequiresTwoDistinctAccurateFixes(){CheckpointGate g=new CheckpointGate();assertNull(step(g,4,5,3,1));assertNull(step(g,4,5,3,1));CheckpointGate.Entry e=step(g,4,5,3,2);assertNotNull(e);assertTrue(e.newEntry);assertFalse(step(g,4,5,3,3).newEntry);}
 @Test public void PoorAccuracyNeverEnlargesEntryRadius(){CheckpointGate g=new CheckpointGate();assertNull(step(g,4,5,8,1));assertNull(step(g,4,5,8,2));assertNull(step(g,6,5,3,3));assertNull(step(g,6,5,3,4));}
 @Test public void InvalidOrOldOrApproximateFixCannotTrigger(){CheckpointGate g=new CheckpointGate();List<CheckpointGate.Candidate> a=Arrays.asList(c("qr",1,5));assertNull(g.update(a,3,11000,1,true,100));assertNull(g.update(a,3,0,2,false,101));assertNull(g.update(a,Float.NaN,0,3,true,102));assertNull(g.update(a,-2,0,4,true,103));}
 @Test public void PanelHidesOutsideConfiguredRadiusWithoutDriftSpam(){CheckpointGate g=new CheckpointGate();step(g,4,5,2,1);assertNotNull(step(g,4,5,2,2));assertNull(step(g,6,5,2,3));CheckpointGate.Entry e=step(g,4,5,2,4);assertNotNull(e);assertFalse(e.newEntry);}
 @Test public void DismissedOrVerifiedCheckpointRearmsOnlyAfterLeaving(){CheckpointGate g=new CheckpointGate();step(g,4,5,2,1);step(g,4,5,2,2);g.dismiss("qr");assertNull(step(g,4,5,2,3));assertNull(step(g,6,5,2,4));assertNull(step(g,8,5,2,5));assertNull(step(g,4,5,2,6));assertTrue(step(g,4,5,2,7).newEntry);}
 @Test public void OverlappingCheckpointsDoNotSwapEveryFix(){CheckpointGate g=new CheckpointGate();List<CheckpointGate.Candidate> a=Arrays.asList(c("one",2,10),c("two",4,10));assertNull(g.update(a,2,0,1,true,100));assertEquals("one",g.update(a,2,0,2,true,101).checkpoint.id);List<CheckpointGate.Candidate> b=Arrays.asList(c("one",5,10),c("two",1,10));assertEquals("one",g.update(b,2,0,3,true,102).checkpoint.id);}
 @Test public void MissingOrNaNCoordinatesAndFutureTimesAreNeverFresh(){assertFalse(TabletPolicy.point(Double.NaN,153));assertFalse(TabletPolicy.point(-27,Double.POSITIVE_INFINITY));assertFalse(TabletPolicy.point(91,153));assertEquals(Long.MAX_VALUE,TabletPolicy.age(0,100000));assertEquals(Long.MAX_VALUE,TabletPolicy.age(300000,100000));assertTrue(TabletPolicy.fresh(99000,100000));assertFalse(TabletPolicy.fresh(1,100000));}
 @Test public void RefreshValidationAndPositionDeduplication(){assertEquals(15,TabletPolicy.interval(-20));assertEquals(30,TabletPolicy.interval(30));assertEquals(60,TabletPolicy.interval(60));assertTrue(TabletPolicy.samePoint(-27,153,-27,153));assertFalse(TabletPolicy.samePoint(-27,153,-27.00001,153));}
}